class FEMenuEntry
{
public:
    int entry_num;
private:
    char padding[0x5c];
public:
    virtual void Draw();
};

class FEMenu
{
    char padding[0x4c];
public:
    FEMenuEntry* highlighted;
};

class TextString
{
    char padding[0x4c];
public:
    virtual void Draw();
};

class PanelQuad
{
    char padding[0x194];
public:
    virtual void TurnOn(bool on);
};

class FEGraphicalMenu
{
    char padding0[0x4c];
public:
    FEMenuEntry* highlighted;
private:
    char padding1[0x110];
public:
    void Draw();
};

class FEMultiMenu : public FEGraphicalMenu
{
    FEMenuEntry* first;
    FEMenuEntry* last;
    FEMenuEntry* secondary_cursor;
};

class TrickBookFrontEnd : public FEMultiMenu
{
    void* sys;
    void* tricks;
    TextString* buttons;
    TextString* trickbook;
    FEMenu* State2[4];
    PanelQuad* arrows[2][2];
    PanelQuad* bkg;
    int arrow_counter;
    int arrow_num;
    bool wait_for_camera;
public:
    void DrawTop();
};

void TrickBookFrontEnd::DrawTop()
{
	if(wait_for_camera) return;

	if(arrow_counter >= 0) arrow_counter--;
	if(arrow_counter < 0 && arrow_counter > -5)
	{
		arrow_counter = -5;
		arrows[0][0]->TurnOn(true);
		arrows[0][1]->TurnOn(false);
		arrows[1][0]->TurnOn(true);
		arrows[1][1]->TurnOn(false);
	}

	FEMultiMenu::Draw();
	State2[highlighted->entry_num]->highlighted->Draw();
	buttons->Draw();
	trickbook->Draw();
}
